if "elicitation" in client_capabilities:
    send_elicitation_request()
else:
    fall_back_to_simple_response()

# a defensive check before attempting a subscription
if server_capabilities.get("resources", {}).get("subscribe"):
    subscribe_to_resource(uri)
else:
    print("Subscriptions not supported by this server")

response = client.send_initialize()
server_caps = response["result"]["capabilities"]
if "prompts" in server_caps:
    show_prompt_menu()
else:
    hide_prompt_menu()

# extending the example to also check for resource support
if "resources" in server_caps:
    enable_resource_browser()

def supported_features(capabilities):
    return [f for f in ["tools", "resources", "prompts"] if f in capabilities]

print(supported_features({"tools": {}, "resources": {"subscribe": True}}))
